// N5.3 Peripheral (Cyberplug): explicit Connected/Autonomous profiles.
import * as S from './states.js?v=109';
export const isCyber=u=>u?.peripheral==='cyberplug';
export const independent=u=>isCyber(u)&&u.cyberplugMode==='autonomous';
export const controller=(u,units)=>isCyber(u)?units.find(v=>v.id===u.controllerId):u;
export const members=(c,units)=>units.filter(v=>isCyber(v)&&v.controllerId===c?.id&&S.present(v));
export const valid=u=>isCyber(u)&&['connected','autonomous'].every(k=>{const p=u.cyberplugProfiles?.[k];return p&&['s','type','mov','mov2','bs','cc','ph','wip','arm','bts','maxhp'].every(key=>p[key]!==undefined)&&Number.isFinite(p.mov)&&Number.isFinite(p.mov2)&&p.loadout?.length;});
export const operational=c=>!!c&&S.active(c)&&!c.offTable&&!S.has(c,'hiddenDeployment')&&!S.has(c,'isolated')&&!S.has(c,'possessed');
export const connectedFor=(u,units)=>{const c=controller(u,units);return members(c,units).find(v=>v.cyberplugMode==='connected'&&S.active(v)&&S.onTable(v));};
const identity=new Set(['id','name','en','team','controllerId','peripheral','cyberplugProfiles','cyberplugMode','x','y','z','facing','prone','states','hp','combatGroup','ammunition','deploymentReviewed']);
export function applyProfile(u,mode){if(!valid(u)||!u.cyberplugProfiles[mode])return false;const wounds=Math.max(0,(u.maxhp??u.cyberplugProfiles[mode].maxhp)-(u.hp??u.cyberplugProfiles[mode].maxhp));for(const key of new Set(Object.values(u.cyberplugProfiles).flatMap(p=>Object.keys(p))))if(!identity.has(key)){if(Object.hasOwn(u.cyberplugProfiles[mode],key))u[key]=structuredClone(u.cyberplugProfiles[mode][key]);else delete u[key];}u.hp=u.maxhp-wounds;u.cyberplugMode=mode;u.noOrders=true;return true;}
export function choose(c,units,id=null){const all=members(c,units);if(!c?.cyberplug||!all.length||all.length>2||all.some(v=>!valid(v))||id&&(!operational(c)||!all.some(v=>v.id===id&&S.active(v)&&!v.offTable)))return false;for(const v of all)applyProfile(v,v.id===id?'connected':'autonomous');c.cyberplugConnectedId=id;c.cyberplugIdle=!!id;delete c.cyberplugReconnect;return true;}
export function initialize(units){for(const c of units.filter(v=>members(v,units).length)){if(c.cyberplugInitialized)continue;c.cyberplugInitialized=true;const all=members(c,units);if(!c.cyberplug||all.some(v=>!valid(v))||all.length>2){c.cyberplugError='Cyberplug需要最多两名附属及精确的连接/自主双配置';continue;}const preferred=all.find(v=>v.cyberplugMode==='connected')||all[0];choose(c,units,operational(c)?preferred.id:null);c.cyberplugControllerUnavailable=!operational(c);}}
export function conclude(units){const events=[];for(const v of units.filter(isCyber)){if(S.has(v,'isolated')&&!S.has(v,'disconnected')){v.states.push('disconnected');events.push(v.name+' 自身孤立：进入断连');}}for(const c of units.filter(v=>members(v,units).length)){if(!operational(c)){if(members(c,units).some(v=>v.cyberplugMode==='connected')){choose(c,units,null);events.push(c.name+' 失能／孤立：Cyberplug在命令结束全部切换自主配置');}c.cyberplugControllerUnavailable=true;}else if(c.cyberplugControllerUnavailable){c.cyberplugControllerUnavailable=false;if(members(c,units).some(v=>S.active(v)&&S.onTable(v)))c.cyberplugReconnect=true;}}return events;}
export const pendingReconnect=units=>units.find(c=>c.cyberplugReconnect&&members(c,units).some(v=>S.active(v)&&S.onTable(v)));
export function supportActor(u,units,point=u){const c=controller(u,units),v=connectedFor(c,units);if(!c||!v||isCyber(u)&&independent(u))return null;return {...c,...(u.id===c.id?point:{}),remoteContactPoints:[{...v,...(u.id===v.id?point:{})}]};}
